import{_ as e,a0 as i,w as r,s as d,ao as a,I as p,x as n,a1 as o,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何在 Ubuntu 中管理開機啓動應用 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中管理開機啓動應用 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中管理開機啓動應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中管理開機啓動應用 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150722 How To Manage StartUp Applications In Ubuntu","title":"如何在 Ubuntu 中管理開機啓動應用","tag":"201508","desc":""},"relativePath":"201508/20150722 How To Manage StartUp Applications In Ubuntu.md","filePath":"[post].md"}'),l={name:"201508/20150722 How To Manage StartUp Applications In Ubuntu.md"};function b(m,t,f,c,g,U){const s=i("Link");return r(),d("div",null,[t[24]||(t[24]=a('<h1 id="如何在-ubuntu-中管理開機啓動應用" tabindex="-1">如何在 Ubuntu 中管理開機啓動應用 <a class="header-anchor" href="#如何在-ubuntu-中管理開機啓動應用" aria-label="Permalink to “如何在 Ubuntu 中管理開機啓動應用”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Manage-Start-up-apps-in-Ubuntu.png" alt="在 Ubuntu 中管理開機啓動應用"></p><p>你曾經考慮過 <strong>在 Ubuntu 中管理開機啓動應用</strong> 嗎？如果在開機時，你的 Ubuntu 系統啓動得非常緩慢，那麼你就需要考慮這個問題了。</p><p>每當你開機進入一個操作系統，一系列的應用將會自動啓動。這些應用被稱為‘開機啓動應用’ 或‘開機啓動程序’。隨着時間的推移，當你在系統中安裝了足夠多的應用時，你將發現有太多的‘開機啓動應用’在開機時自動地啓動了，它們吃掉了很多的系統資源，並將你的系統拖慢。這可能會讓你感覺卡頓，我想這種情況並不是你想要的。</p><p>讓 Ubuntu 變得更快的方法之一是對這些開機啓動應用進行控制。 Ubuntu 為你提供了一個 GUI 工具來讓你找到這些開機啓動應用，然後完全禁止或延遲它們的啓動，這樣就可以不讓每個應用在開機時同時運行。</p><p>在這篇文章中，我們將看到 <strong>在 Ubuntu 中，如何控制開機啓動應用，如何讓一個應用在開機時啓動以及如何發現隱藏的開機啓動應用。</strong>這裏提供的指導對所有的 Ubuntu 版本均適用，例如 Ubuntu 12.04, Ubuntu 14.04 和 Ubuntu 15.04。</p><h3 id="在-ubuntu-中管理開機啓動應用" tabindex="-1">在 Ubuntu 中管理開機啓動應用 <a class="header-anchor" href="#在-ubuntu-中管理開機啓動應用" aria-label="Permalink to “在 Ubuntu 中管理開機啓動應用”">​</a></h3><p>默認情況下， Ubuntu 提供了一個<code>Startup Applications</code>工具來供你使用，你不必再進行安裝。只需到 Unity 面板中就可以查找到該工具。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/startup_applications_Ubuntu.jpeg" alt="ubuntu 中的開機啓動應用工具"></p><p>點擊它來啓動。下面是我的<code>Startup Applications</code>的樣子：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Screenshot-from-2015-07-18-122550.png" alt="在 Ubuntu 中查看開機啓動程序"></p><h3 id="在-ubuntu-中移除開機啓動應用" tabindex="-1">在 Ubuntu 中移除開機啓動應用 <a class="header-anchor" href="#在-ubuntu-中移除開機啓動應用" aria-label="Permalink to “在 Ubuntu 中移除開機啓動應用”">​</a></h3>',12)),p("p",null,[t[1]||(t[1]=n("現在由你來發現哪個程序對你用處不大，對我來説，是 ",-1)),o(s,{href:"https://wiki.gnome.org/action/show/Projects/Caribou?action=show&redirect=Caribou"},{default:u(()=>[...t[0]||(t[0]=[n("Caribou",-1)])]),_:1}),t[2]||(t[2]=n(" 這個軟件，它是一個屏幕鍵盤程序，在開機時它並沒有什麼用處，所以我想將它移除出開機啓動程序的列表中。",-1))]),t[25]||(t[25]=a('<p>你可以選擇阻止某個程序在開機時啓動，而在開機啓動程序列表中保留該選項以便以後再進行激活。點擊 <code>關閉</code>按鈕來保留你的偏好設置。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/startup_applications_ubuntu_2.png" alt="在 Ubuntu 中移除開機啓動程序"></p><p>要將一個程序從開機啓動程序列表中移除，選擇對應的選項然後從窗口右邊的面板中點擊<code>移除</code>按鈕來保留你的偏好設置。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/startup_applications_Ubuntu_1.jpeg" alt="在 Ubuntu 中將程序從開機啓動列表中移除"></p><p>需要提醒的是，這並不會將該程序卸載掉，只是讓該程序不再在每次開機時自動啓動。你可以對所有你不喜歡的程序做類似的處理。</p><h3 id="讓開機啓動程序延遲啓動" tabindex="-1">讓開機啓動程序延遲啓動 <a class="header-anchor" href="#讓開機啓動程序延遲啓動" aria-label="Permalink to “讓開機啓動程序延遲啓動”">​</a></h3><p>若你並不想在開機啓動列表中移除掉程序，但同時又憂慮着系統性能的問題，那麼你所需要做的是給程序添加一個延遲啓動命令，這樣所有的程序就不會在開機時同時啓動。</p><p>選擇一個程序然後點擊 <code>編輯</code> 按鈕。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/startup_applications_ubuntu_3.png" alt="編輯開機啓動應用列表"></p><p>這將展示出運行這個特定的程序所需的命令。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/startup_applications_ubuntu_4.jpg" alt="在開機啓動列表的程序運行所需的命令"></p>',11)),p("p",null,[t[4]||(t[4]=n("所有你需要做的就是在程序運行命令前添加一句 ",-1)),t[5]||(t[5]=p("code",null,"sleep XX;",-1)),t[6]||(t[6]=n(" 。這樣就為實際運行該命令來啓動的對應程序添加了 ",-1)),t[7]||(t[7]=p("code",null,"XX",-1)),t[8]||(t[8]=n(" 秒的延遲。例如，假如我想讓 Variety ",-1)),o(s,{href:"http://itsfoss.com/applications-manage-wallpapers-ubuntu/"},{default:u(()=>[...t[3]||(t[3]=[n("壁紙管理應用",-1)])]),_:1}),t[9]||(t[9]=n(" 延遲啓動 2 分鐘，我就需要像下面那樣在命令前添加 ",-1)),t[10]||(t[10]=p("code",null,"sleep 120;",-1))]),t[26]||(t[26]=a(`<p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/startup_applications_ubuntu_5.png" alt="在 Ubuntu 中延遲開機啓動的程序"></p><p>保存並關閉設置。你將在下一次啓動時看到效果。</p><h3 id="增添一個程序到開機啓動應用列表中" tabindex="-1">增添一個程序到開機啓動應用列表中 <a class="header-anchor" href="#增添一個程序到開機啓動應用列表中" aria-label="Permalink to “增添一個程序到開機啓動應用列表中”">​</a></h3><p>這對於新手來説需要一點技巧。我們知道，在 Linux 的底層都是一些命令，在上一節我們看到這些開機啓動程序只是在每次開機時運行一些命令。假如你想在開機啓動列表中添加一個新的程序，你需要知道運行該應用所需的命令。</p><h4 id="第-1-步-如何查找運行一個程序所需的命令" tabindex="-1">第 1 步：如何查找運行一個程序所需的命令？ <a class="header-anchor" href="#第-1-步-如何查找運行一個程序所需的命令" aria-label="Permalink to “第 1 步：如何查找運行一個程序所需的命令？”">​</a></h4><p>首先來到 Unity Dash 面板然後搜索 <code>Main Menu</code>:</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Program_menu_Ubuntu.jpg" alt="Ubuntu 下的程序菜單"></p><p>這將展示出在各種類別下你安裝的所有程序。在 Ubuntu 的低版本中，你將看到一個相似的菜單，通過它來選擇並運行應用。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Main_menu_ubuntu.jpeg" alt="Ubuntu 下的 main menu "></p><p>在各種類別下找到你找尋的應用，然後點擊 <code>屬性</code> 按鈕來查看運行該應用所需的命令。例如，我想在開機時運行 <code>Transmission Torrent 客户端</code>。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Main_menu_ubuntu_1.jpeg" alt="在 Ubuntu 下查找運行程序所需的命令"></p><p>這就會向我給出運行 <code>Transmission</code> 應用的命令：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/startup_programs_commands.png" alt="在 Ubuntu 下查找運行某個程序所需的命令"></p><p>接着，我將用相同的信息來將 <code>Transmission</code> 應用添加到開機啓動列表中。</p><h4 id="第-2-步-添加一個程序到開機啓動列表中" tabindex="-1">第 2 步： 添加一個程序到開機啓動列表中 <a class="header-anchor" href="#第-2-步-添加一個程序到開機啓動列表中" aria-label="Permalink to “第 2 步： 添加一個程序到開機啓動列表中”">​</a></h4><p>再次來到開機啓動應用工具中並點擊 <code>添加</code> 按鈕。這將讓你輸入一個應用的名稱，對應的命令和相關的描述。其中命令最為重要，你可以使用任何你想用的名稱和描述。使用上一步得到的命令然後點擊 <code>添加</code> 按鈕。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Add_startup_program_Ubuntu.jpg" alt="在 Ubuntu 中添加一個開機啓動程序"></p><p>就這樣，你將在下一次開機時看到這個程序會自動運行。這就是在 Ubuntu 中你能做的關於開機啓動應用的所有事情。</p><p>到現在為止，我們已經討論在開機時可見到的應用，但仍有更多的服務，守護進程和程序並不在<code>開機啓動應用工具</code>中可見。下一節中，我們將看到如何在 Ubuntu 中查看這些隱藏的開機啓動程序。</p><h3 id="在-ubuntu-中查看隱藏的開機啓動程序" tabindex="-1">在 Ubuntu 中查看隱藏的開機啓動程序 <a class="header-anchor" href="#在-ubuntu-中查看隱藏的開機啓動程序" aria-label="Permalink to “在 Ubuntu 中查看隱藏的開機啓動程序”">​</a></h3><p>要查看在開機時哪些服務在運行，可以打開一個終端並使用下面的命令：</p><pre><code>sudo sed -i &#39;s/NoDisplay=true/NoDisplay=false/g&#39; /etc/xdg/autostart/*.desktop
</code></pre><p>上面的命令是一個快速查找和替換命令，它將在所有自動啓動的程序裏的 <code>NoDisplay=false</code> 改為 <code>NoDisplay=true</code> ，一旦執行了這個命令後，再次打開<code>開機啓動應用工具</code>，現在你應該可以看到更多的程序：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Hidden_startup_program_Ubuntu.jpg" alt="在 Ubuntu 中查看隱藏的開機啓動程序"></p><p>你可以像先前我們討論的那樣管理這些開機啓動應用。我希望這篇教程可以幫助你在 Ubuntu 中控制開機啓動程序。任何的問題或建議總是歡迎的。</p><hr>`,26)),p("p",null,[t[12]||(t[12]=n("via: ",-1)),o(s,{href:"http://itsfoss.com/manage-startup-applications-ubuntu/"},{default:u(()=>[...t[11]||(t[11]=[n("http://itsfoss.com/manage-startup-applications-ubuntu/",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=n("作者：",-1)),o(s,{href:"http://itsfoss.com/author/abhishek/"},{default:u(()=>[...t[13]||(t[13]=[n("Abhishek",-1)])]),_:1}),t[17]||(t[17]=n(" 譯者：",-1)),o(s,{href:"https://github.com/FSSlc"},{default:u(()=>[...t[14]||(t[14]=[n("FSSlc",-1)])]),_:1}),t[18]||(t[18]=n(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[15]||(t[15]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[21]||(t[21]=n("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[19]||(t[19]=[n("LCTT",-1)])]),_:1}),t[22]||(t[22]=n(" 原創翻譯，",-1)),o(s,{href:"https://linux.cn/"},{default:u(()=>[...t[20]||(t[20]=[n("Linux中國",-1)])]),_:1}),t[23]||(t[23]=n(" 榮譽推出",-1))])])}const w=e(l,[["render",b]]);export{h as __pageData,w as default};
